const SR = 24000;
const HANGUL = /[가-힣]/g;

function generate(text: string, exaggeration = 0.5, cfgWeight = 0.5, seed = 0, ref: { f0: number; depth: number } | null = null): Float32Array {
  // Chatterbox 흉내: 손잡이 -> 말 빠르기 · 음높이 폭 · 세기 변화 (신경망 대신 규칙 · 사인파)
  const r = rng(seed);
  const nSyl = Math.max((text.match(HANGUL) ?? []).length, 1);
  const rate = 3.5 + 2.5 * cfgWeight; // 음절/초: cfg_weight가 낮을수록 천천히 또박또박
  const sec = nSyl / rate + 0.4;
  const base = ref ? ref.f0 : 200; // 참고 음성이 있으면 그 목소리 높이 · 표현 폭을 따라간다
  const depth = ref ? ref.depth : 1;
  const phi = r() * 2 * Math.PI;
  const q = text.trimEnd().endsWith("?");
  const ex = text.trimEnd().endsWith("!");
  const y = new Float32Array(Math.floor(sec * SR));
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    const t = i / SR;
    let st = (((2 + 10 * exaggeration) * depth) / 2) * Math.sin(2 * Math.PI * (rate / 2) * t + phi); // 반음 단위 억양
    if (q) st += 4 * Math.min(1, Math.max(0, (t - (sec - 0.8)) / 0.6)); // 물음표: 끝이 올라감
    if (ex) st += 2; // 느낌표: 전체가 높아짐
    phase += (2 * Math.PI * base * 2 ** (st / 12)) / SR;
    const amp = 0.3 * (1 + 0.6 * exaggeration * Math.sin(2 * Math.PI * rate * t)) * (t < sec - 0.2 ? 1 : 0); // 끝 0.2초는 쉼
    y[i] = amp * Math.sin(phase);
  }
  return y;
}

function frameF0(y: Float32Array, sr = SR, frameSec = 0.05): { f0: number[]; hop: number } {
  // 50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 NaN
  const n = Math.floor(frameSec * sr);
  const hop = Math.floor(n / 2);
  const f0: number[] = [];
  for (let a = 0; a < y.length - n; a += hop) {
    const ts: number[] = [];
    let peak = 0;
    for (let i = 0; i < n; i++) {
      peak = Math.max(peak, Math.abs(y[a + i]));
      if (i > 0 && y[a + i - 1] < 0 && y[a + i] >= 0) ts.push(i - 1 + -y[a + i - 1] / (y[a + i] - y[a + i - 1])); // 샘플 사이를 직선으로 보간
    }
    f0.push(peak < 0.02 || ts.length < 3 ? NaN : ((ts.length - 1) / (ts[ts.length - 1] - ts[0])) * sr);
  }
  return { f0, hop };
}

const median = (x: number[]): number => { const s = [...x].sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)] / 2 + s[Math.ceil((s.length - 1) / 2)] / 2; };
const percentile = (x: number[], p: number): number => {
  const s = [...x].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
};

function prosody(y: Float32Array, sr = SR, text: string | null = null) {
  // 운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초
  const { f0, hop } = frameF0(y, sr);
  const v = f0.filter((x) => !Number.isNaN(x));
  const med = median(v);
  const st = v.map((x) => 12 * Math.log2(x / med)); // 중앙값 대비 반음
  const db: number[] = [];
  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

function styleFrom(y: Float32Array): { f0: number; depth: number } {
  // 참고 음성에서 '말투 조건'을 뽑는다: 목소리 높이 + 표현 폭 (진짜는 화자 임베딩 · 참고 토큰)
  const p = prosody(y);
  return { f0: p.pitchHz, depth: p.rangeSt / 7.0 }; // 7 = 기본 손잡이(exaggeration 0.5)의 음높이 폭(반음)
}

function embed(y: Float32Array): number[] {
  // 화자 특징 3개: 높이(옥타브) · 폭 · 세기 변화
  const p = prosody(y);
  return [Math.log2(p.pitchHz / 200), p.rangeSt / 12, p.energyDb / 6];
}

function speakerSim(a: Float32Array, b: Float32Array): number {
  // 특징 사이 거리가 가까울수록 1에 가까운 유사도
  const ea = embed(a);
  const eb = embed(b);
  return 1 / (1 + Math.sqrt(ea.reduce((s, v, i) => s + (v - eb[i]) ** 2, 0)));
}

const text = "내일 다시 오신다고요";
const exLo = prosody(generate(text + ".", 0.25, 0.5, 1));
const exHi = prosody(generate(text + ".", 1.0, 0.5, 1));
const cwLo = prosody(generate(text + ".", 0.5, 0.2, 1), SR, text);
const cwHi = prosody(generate(text + ".", 0.5, 0.8, 1), SR, text);
const tail: Record<string, number> = {};
for (const p of [".", "?", "!"]) tail[p] = tailSemitone(generate(text + p, 0.5, 0.5, 1));
const ref = styleFrom(generate("참고 음성이에요", 0.5, 0.5, 2, { f0: 260, depth: 1.4 })); // 높은 목소리 · 표현이 큰 참고 음성
const styled = prosody(generate(text + ".", 0.5, 0.5, 1, ref));
const base = prosody(generate(text + ".", 0.5, 0.5, 1));

console.log(`1) 문장 부호: 끝 0.6초 반음  . ${tail["."].toFixed(1)} · ? ${tail["?"].toFixed(1)} · ! ${tail["!"].toFixed(1)}`);
console.log(`2) exaggeration 0.25 -> 1.0: 음높이 폭 ${exLo.rangeSt.toFixed(1)} -> ${exHi.rangeSt.toFixed(1)} 반음 · 세기 변화 ${exLo.energyDb.toFixed(1)} -> ${exHi.energyDb.toFixed(1)} dB`);
console.log(`3) cfg_weight 0.2 -> 0.8: ${cwLo.sylPerSec.toFixed(1)} -> ${cwHi.sylPerSec.toFixed(1)} 음절/초 (낮을수록 천천히)`);
console.log(`4) 참고 음성: 음높이 ${base.pitchHz.toFixed(0)} -> ${styled.pitchHz.toFixed(0)} Hz`);
check(tail["?"] > tail["."] + 1 && exHi.rangeSt > exLo.rangeSt && exHi.energyDb > exLo.energyDb
  && cwHi.sylPerSec > cwLo.sylPerSec && styled.pitchHz > base.pitchHz + 30);

arch.typescript:
// D18 · Part 2 · Chatterbox 해부: 글자 → 소리 토큰(AR) → 소리, 토큰 수 → 소리 길이 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d18_arch.ts
//   T3(자기회귀)가 25 토큰/초 소리 토큰을 한 개씩 만들고, 디코더가 토큰마다 소리 960 샘플을 만든다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const TOKEN_HZ = 25; // 소리 토큰 25개/초
const SPEECH_SR = 24000;
const STOP = 6561; // 끝 신호
const SAMPLES_PER_TOKEN = SPEECH_SR / TOKEN_HZ; // 토큰 1개 = 960 샘플 (40 ms)
const HANGUL = /[가-힣]/g;

function t3Generate(text: string, seed = 0): number[] {
  // 자기회귀(AR): 앞 토큰을 보고 다음 토큰을 하나씩. 글자 수에 맞는 길이에서 끝 신호를 낸다 (장난감 규칙)
  const r = rng(seed);
  const target = Math.ceil(((text.match(HANGUL) ?? []).length / 4.5) * TOKEN_HZ) + Math.floor(r() * 3);
  const out: number[] = [];
  for (;;) {
    const tok = out.length >= target ? STOP : Math.floor(r() * 6561); // 한 번 호출 = 토큰 1개
    if (tok === STOP) return out;
    out.push(tok);
  }
}

function s3genDecode(tokens: number[]): Float32Array {
  // 토큰 -> 파형: 토큰마다 960 샘플. 토큰 값이 음높이를 정한다 (진짜는 flow matching + 보코더)
  const y = new Float32Array(tokens.length * SAMPLES_PER_TOKEN);
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    phase += (2 * Math.PI * (120 + (tokens[Math.floor(i / SAMPLES_PER_TOKEN)] % 100))) / SPEECH_SR;
    y[i] = 0.3 * Math.sin(phase);
  }
  return y;
}

const text = "안녕하세요 반갑습니다 오늘도 좋은 하루 보내세요";
const tokens = t3Generate(text);
const wav = s3genDecode(tokens);
console.log(`글자 ${(text.match(HANGUL) ?? []).length}음절 -> 소리 토큰 ${tokens.length}개 (T3 호출 ${tokens.length + 1}번) -> 파형 ${wav.length} 샘플 = ${(wav.length / SPEECH_SR).toFixed(2)}초`);
check(wav.length === tokens.length * SAMPLES_PER_TOKEN && Math.abs(wav.length / SPEECH_SR - tokens.length / TOKEN_HZ) < 1e-9
  && SAMPLES_PER_TOKEN === 960 && tokens.every((t) => t !== STOP), "소리 길이(초) = 토큰 수 / 25");

cfg.typescript:
// D18 · Part 3 · CFG 식을 직접 계산하기: cond + w x (cond − uncond) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d18_cfg.ts
//   글자를 보고 한 예측과 가리고 한 예측을 섞어 글자를 더 따르게 만든다. cfg_weight별 토큰 확률표
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function cfgMix(cond: number[], uncond: number[], w: number): number[] {
  // 글자를 본 예측 + w x (본 예측 - 가린 예측)
  return cond.map((c, i) => c + w * (c - uncond[i]));
}

function softmax(x: number[]): number[] {
  const m = Math.max(...x);
  const e = x.map((v) => Math.exp(v - m));
  const s = e.reduce((a, b) => a + b, 0);
  return e.map((v) => v / s);
}

const cond = [2.2, 1.6, 0.4, 0.1]; // 글자를 보고 한 예측 (토큰 A ~ D)
const uncond = [1.2, 1.7, 0.9, 0.2]; // 글자를 가리고 한 예측
for (const w of [0.0, 0.3, 0.5, 1.0]) {
  const p = softmax(cfgMix(cond, uncond, w));
  console.log(`cfg_weight ${w}: ` + p.map((v, i) => `P(${"ABCD"[i]}) ${v.toFixed(3)}`).join(" "));
}

const p0 = softmax(cfgMix(cond, uncond, 0.0));
const p1 = softmax(cfgMix(cond, uncond, 1.0));
check(cfgMix(cond, uncond, 0.0).every((v, i) => v === cond[i])
  && cfgMix(cond, uncond, 1.0).every((v, i) => Math.abs(v - (2 * cond[i] - uncond[i])) < 1e-12)
  && p1[0] > p0[0], "w=0이면 cond 그대로, w=1이면 2 x cond - uncond, 글자가 밀던 토큰 A 확률은 올라가야 해요");

prompt.typescript:
// D18 · Part 4 · 참고 음성 → 조건: 말투 옮기기와 프롬프트 토큰 상한 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d18_prompt.ts
//   참고 음성에서 높이 · 폭을 뽑아 새 문장에 입히고, 참고 길이와 무관하게 프롬프트 토큰은 최대 150개(6초)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const SR = 24000;
const HANGUL = /[가-힣]/g;

function generate(text: string, exaggeration = 0.5, cfgWeight = 0.5, seed = 0, ref: { f0: number; depth: number } | null = null): Float32Array {
  // Chatterbox 흉내: 손잡이 -> 말 빠르기 · 음높이 폭 · 세기 변화 (신경망 대신 규칙 · 사인파)
  const r = rng(seed);
  const nSyl = Math.max((text.match(HANGUL) ?? []).length, 1);
  const rate = 3.5 + 2.5 * cfgWeight; // 음절/초: cfg_weight가 낮을수록 천천히 또박또박
  const sec = nSyl / rate + 0.4;
  const base = ref ? ref.f0 : 200; // 참고 음성이 있으면 그 목소리 높이 · 표현 폭을 따라간다
  const depth = ref ? ref.depth : 1;
  const phi = r() * 2 * Math.PI;
  const q = text.trimEnd().endsWith("?");
  const ex = text.trimEnd().endsWith("!");
  const y = new Float32Array(Math.floor(sec * SR));
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    const t = i / SR;
    let st = (((2 + 10 * exaggeration) * depth) / 2) * Math.sin(2 * Math.PI * (rate / 2) * t + phi); // 반음 단위 억양
    if (q) st += 4 * Math.min(1, Math.max(0, (t - (sec - 0.8)) / 0.6)); // 물음표: 끝이 올라감
    if (ex) st += 2; // 느낌표: 전체가 높아짐
    phase += (2 * Math.PI * base * 2 ** (st / 12)) / SR;
    const amp = 0.3 * (1 + 0.6 * exaggeration * Math.sin(2 * Math.PI * rate * t)) * (t < sec - 0.2 ? 1 : 0); // 끝 0.2초는 쉼
    y[i] = amp * Math.sin(phase);
  }
  return y;
}

function frameF0(y: Float32Array, sr = SR, frameSec = 0.05): { f0: number[]; hop: number } {
  // 50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 NaN
  const n = Math.floor(frameSec * sr);
  const hop = Math.floor(n / 2);
  const f0: number[] = [];
  for (let a = 0; a < y.length - n; a += hop) {
    const ts: number[] = [];
    let peak = 0;
    for (let i = 0; i < n; i++) {
      peak = Math.max(peak, Math.abs(y[a + i]));
      if (i > 0 && y[a + i - 1] < 0 && y[a + i] >= 0) ts.push(i - 1 + -y[a + i - 1] / (y[a + i] - y[a + i - 1])); // 샘플 사이를 직선으로 보간
    }
    f0.push(peak < 0.02 || ts.length < 3 ? NaN : ((ts.length - 1) / (ts[ts.length - 1] - ts[0])) * sr);
  }
  return { f0, hop };
}

const median = (x: number[]): number => { const s = [...x].sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)] / 2 + s[Math.ceil((s.length - 1) / 2)] / 2; };
const percentile = (x: number[], p: number): number => {
  const s = [...x].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
};

function prosody(y: Float32Array, sr = SR, text: string | null = null) {
  // 운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초
  const { f0, hop } = frameF0(y, sr);
  const v = f0.filter((x) => !Number.isNaN(x));
  const med = median(v);
  const st = v.map((x) => 12 * Math.log2(x / med)); // 중앙값 대비 반음
  const db: number[] = [];
  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

function styleFrom(y: Float32Array): { f0: number; depth: number } {
  // 참고 음성에서 '말투 조건'을 뽑는다: 목소리 높이 + 표현 폭 (진짜는 화자 임베딩 · 참고 토큰)
  const p = prosody(y);
  return { f0: p.pitchHz, depth: p.rangeSt / 7.0 }; // 7 = 기본 손잡이(exaggeration 0.5)의 음높이 폭(반음)
}

function embed(y: Float32Array): number[] {
  // 화자 특징 3개: 높이(옥타브) · 폭 · 세기 변화
  const p = prosody(y);
  return [Math.log2(p.pitchHz / 200), p.rangeSt / 12, p.energyDb / 6];
}

function speakerSim(a: Float32Array, b: Float32Array): number {
  // 특징 사이 거리가 가까울수록 1에 가까운 유사도
  const ea = embed(a);
  const eb = embed(b);
  return 1 / (1 + Math.sqrt(ea.reduce((s, v, i) => s + (v - eb[i]) ** 2, 0)));
}

const TOKEN_HZ = 25;
const MAX_PROMPT_TOKENS = 150;
// 참고 음성이 길어도 앞 6초(150 토큰)만 쓴다
const promptTokens = (refSec: number): number => Math.min(MAX_PROMPT_TOKENS, Math.floor(refSec * TOKEN_HZ));

const calm = generate("네, 알겠습니다. 천천히 설명해 드릴게요.", 0.3, 0.5, 3, { f0: 170, depth: 0.8 });
const excited = generate("우와, 이거 진짜 대박이다!", 1.0, 0.5, 3, { f0: 280, depth: 1.5 });
const calm2 = generate("오늘 날씨가 정말 좋네요.", 0.3, 0.5, 9, { f0: 170, depth: 0.8 }); // 같은 목소리, 다른 문장
const sims = [speakerSim(calm, calm2), speakerSim(calm, excited)];
console.log(`같은 목소리 유사도 ${sims[0].toFixed(2)} · 다른 목소리 ${sims[1].toFixed(2)}`);

const TARGET = "우리 내일 아침에 다시 이야기해요.";
for (const [name, refY] of [["기본 목소리", null], ["차분한 참고", calm], ["신나는 참고", excited]] as [string, Float32Array | null][]) {
  const y = generate(TARGET, 0.5, 0.5, 5, refY ? styleFrom(refY) : null);
  console.log(`${name}: 음높이 ${prosody(y).pitchHz.toFixed(0)} Hz`);
}
const styled = prosody(generate(TARGET, 0.5, 0.5, 5, styleFrom(excited))).pitchHz;
console.log("참고 음성 길이 3초 · 6초 · 10초 -> 프롬프트 토큰", [3, 6, 10].map(promptTokens));
check(sims[0] > 0.9 && sims[0] > sims[1] && styled > 250 && [3, 6, 10].map(promptTokens).join() === "75,150,150");

f5.typescript:
// D18 · Part 5 · F5-TTS: 길이는 글자 바이트 비율로, 품질은 다듬는 횟수(nfe_step)로 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d18_f5.ts
//   생성 길이 = 참고 음성 초 / 참고 글자 바이트 x 생성 글자 바이트 / speed, nfe_step은 Euler 적분 횟수(오차 ~ 1/nfe)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const REF_SEC = 6.2;
const REF_TEXT = "Some call me nature, others call me mother nature.";
const SR = 24000;
const HOP = 256;
const bytes = (s: string): number => new TextEncoder().encode(s).length;

function f5Seconds(genText: string, speed = 1.0): number {
  // 참고 음성의 '바이트당 시간'으로 새 글자 바이트 수를 곱해 길이를 정한다 (한글은 글자당 3바이트!)
  return ((REF_SEC / bytes(REF_TEXT)) * bytes(genText)) / speed;
}

function eulerError(nfe: number): number {
  // flow matching 흉내: 곡선 x(t) = sin(pi t / 2) 를 nfe번 Euler로 따라가 끝값 오차를 잰다 (정답 1.0)
  let x = 0;
  const dt = 1 / nfe;
  for (let k = 0; k < nfe; k++) x += dt * (Math.PI / 2) * Math.cos((Math.PI / 2) * k * dt); // 속도(미분)를 nfe번 호출
  return Math.abs(1 - x);
}

const GEN_EN = "Expressive speech makes a voice assistant sound friendly and natural.";
const gap = (s: number): number => {
  const pred = f5Seconds(GEN_EN, s);
  return Math.abs(pred - (Math.ceil((pred * SR) / HOP) * HOP) / SR) / pred; // 실제로는 mel 프레임 정수 개로 만든다
};
for (const sp of [0.8, 1.0, 1.3]) {
  const pred = f5Seconds(GEN_EN, sp);
  console.log(`speed ${sp}: 예측 ${pred.toFixed(2)}초 · 실제 ${((Math.ceil((pred * SR) / HOP) * HOP) / SR).toFixed(2)}초`);
}
const errs = [8, 16, 32].map(eulerError);
console.log("nfe_step별 오차(호출 횟수가 곧 시간):", errs.map((e) => e.toFixed(4)).join(" > "));
const ratio = f5Seconds("안녕하세요") / f5Seconds("hello"); // 5글자 한글(15바이트) vs 5글자 영어(5바이트)
check([0.8, 1.0, 1.3].every((s) => gap(s) < 0.06) && errs[0] > errs[1] && errs[1] > errs[2] && Math.abs(ratio - 3) < 1e-9,
  "길이는 speed로 나누고, nfe가 커질수록 오차는 줄어야 해요");

compare.typescript:
// D18 · Part 6 · 같은 조건 비교표와 워터마크 검출 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d18_compare.ts
//   같은 문장 · 같은 씨앗으로 두 시스템 소리를 만들어 화자 유사도 · 워터마크를 표로 비교 (문장 1개 · 씨앗 1개라 순위는 확정 못 함)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const SR = 24000;
const HANGUL = /[가-힣]/g;

function generate(text: string, exaggeration = 0.5, cfgWeight = 0.5, seed = 0, ref: { f0: number; depth: number } | null = null): Float32Array {
  // Chatterbox 흉내: 손잡이 -> 말 빠르기 · 음높이 폭 · 세기 변화 (신경망 대신 규칙 · 사인파)
  const r = rng(seed);
  const nSyl = Math.max((text.match(HANGUL) ?? []).length, 1);
  const rate = 3.5 + 2.5 * cfgWeight; // 음절/초: cfg_weight가 낮을수록 천천히 또박또박
  const sec = nSyl / rate + 0.4;
  const base = ref ? ref.f0 : 200; // 참고 음성이 있으면 그 목소리 높이 · 표현 폭을 따라간다
  const depth = ref ? ref.depth : 1;
  const phi = r() * 2 * Math.PI;
  const q = text.trimEnd().endsWith("?");
  const ex = text.trimEnd().endsWith("!");
  const y = new Float32Array(Math.floor(sec * SR));
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    const t = i / SR;
    let st = (((2 + 10 * exaggeration) * depth) / 2) * Math.sin(2 * Math.PI * (rate / 2) * t + phi); // 반음 단위 억양
    if (q) st += 4 * Math.min(1, Math.max(0, (t - (sec - 0.8)) / 0.6)); // 물음표: 끝이 올라감
    if (ex) st += 2; // 느낌표: 전체가 높아짐
    phase += (2 * Math.PI * base * 2 ** (st / 12)) / SR;
    const amp = 0.3 * (1 + 0.6 * exaggeration * Math.sin(2 * Math.PI * rate * t)) * (t < sec - 0.2 ? 1 : 0); // 끝 0.2초는 쉼
    y[i] = amp * Math.sin(phase);
  }
  return y;
}

function frameF0(y: Float32Array, sr = SR, frameSec = 0.05): { f0: number[]; hop: number } {
  // 50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 NaN
  const n = Math.floor(frameSec * sr);
  const hop = Math.floor(n / 2);
  const f0: number[] = [];
  for (let a = 0; a < y.length - n; a += hop) {
    const ts: number[] = [];
    let peak = 0;
    for (let i = 0; i < n; i++) {
      peak = Math.max(peak, Math.abs(y[a + i]));
      if (i > 0 && y[a + i - 1] < 0 && y[a + i] >= 0) ts.push(i - 1 + -y[a + i - 1] / (y[a + i] - y[a + i - 1])); // 샘플 사이를 직선으로 보간
    }
    f0.push(peak < 0.02 || ts.length < 3 ? NaN : ((ts.length - 1) / (ts[ts.length - 1] - ts[0])) * sr);
  }
  return { f0, hop };
}

const median = (x: number[]): number => { const s = [...x].sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)] / 2 + s[Math.ceil((s.length - 1) / 2)] / 2; };
const percentile = (x: number[], p: number): number => {
  const s = [...x].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
};

function prosody(y: Float32Array, sr = SR, text: string | null = null) {
  // 운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초
  const { f0, hop } = frameF0(y, sr);
  const v = f0.filter((x) => !Number.isNaN(x));
  const med = median(v);
  const st = v.map((x) => 12 * Math.log2(x / med)); // 중앙값 대비 반음
  const db: number[] = [];
  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

function styleFrom(y: Float32Array): { f0: number; depth: number } {
  // 참고 음성에서 '말투 조건'을 뽑는다: 목소리 높이 + 표현 폭 (진짜는 화자 임베딩 · 참고 토큰)
  const p = prosody(y);
  return { f0: p.pitchHz, depth: p.rangeSt / 7.0 }; // 7 = 기본 손잡이(exaggeration 0.5)의 음높이 폭(반음)
}

function embed(y: Float32Array): number[] {
  // 화자 특징 3개: 높이(옥타브) · 폭 · 세기 변화
  const p = prosody(y);
  return [Math.log2(p.pitchHz / 200), p.rangeSt / 12, p.energyDb / 6];
}

function speakerSim(a: Float32Array, b: Float32Array): number {
  // 특징 사이 거리가 가까울수록 1에 가까운 유사도
  const ea = embed(a);
  const eb = embed(b);
  return 1 / (1 + Math.sqrt(ea.reduce((s, v, i) => s + (v - eb[i]) ** 2, 0)));
}

const WM_REL = 0.1; // 워터마크 세기 = 소리 크기(rms)의 10%
const HOLD = 4; // 같은 값을 4샘플씩 유지(낮은 소리 쪽에 모여 전화 음질에도 남음)

function wmKey(n: number, secret = 1234): Float64Array {
  // 비밀 값에서 만든 +1/-1 열 (xorshift32). 같은 비밀이면 같은 열 -> 검출기가 알아본다
  let x = secret >>> 0;
  const out = new Float64Array(n);
  for (let i = 0; i < n; i += HOLD) {
    x = (x ^ (x << 13)) >>> 0;
    x = (x ^ (x >>> 17)) >>> 0;
    x = (x ^ (x << 5)) >>> 0;
    for (let j = i; j < Math.min(i + HOLD, n); j++) out[j] = x & 1 ? 1 : -1;
  }
  return out;
}

function rms(y: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * y[i];
  return Math.sqrt(s / y.length) + 1e-12;
}

function applyWatermark(y: Float32Array): Float32Array {
  // 소리에 비밀 열을 작게 더한다 (Perth 워터마커의 아이디어만 흉내)
  const k = wmKey(y.length);
  const r = rms(y);
  return Float32Array.from(y, (v, i) => v + WM_REL * r * k[i]);
}

function getWatermark(y: Float32Array): number {
  // 비밀 열과 얼마나 닮았나 0~1 (소리 크기와 무관). 0.5 이상이면 '워터마크 있음'. 시작 위치가 어긋나면 못 찾는다
  const k = wmKey(y.length);
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * k[i];
  return Math.min(1, Math.max(0, s / y.length / (WM_REL * rms(y))));
}

const REF = generate("참고 음성이에요 안녕하세요", 0.5, 0.5, 4, { f0: 230, depth: 1.1 });
const style = styleFrom(REF);
const TEXT = "안녕하세요 오늘 회의는 세 시에 시작합니다";
const systems: Record<string, Float32Array> = {
  Chatterbox: applyWatermark(generate(TEXT, 0.5, 0.5, 0, style)), // 이 모델은 자동으로 워터마크를 넣는다
  "F5-TTS": generate(TEXT, 0.4, 0.7, 0, style), // 이 모델은 넣지 않는다
};
console.log(`${"모델".padEnd(12)} ${"길이(초)".padStart(8)} ${"화자유사도".padStart(10)} ${"워터마크".padStart(8)}`);
const rows: Record<string, number[]> = {};
for (const [name, y] of Object.entries(systems)) {
  rows[name] = [y.length / SR, speakerSim(y, REF), getWatermark(y)];
  console.log(`${name.padEnd(12)} ${rows[name][0].toFixed(2).padStart(8)} ${rows[name][1].toFixed(3).padStart(10)} ${rows[name][2].toFixed(2).padStart(8)}`);
}
const refWm = getWatermark(REF);
console.log(`${"(참고 음성)".padEnd(12)} ${"".padStart(8)} ${(1).toFixed(3).padStart(10)} ${refWm.toFixed(2).padStart(8)}`);
check(rows["Chatterbox"][2] > 0.5 && rows["F5-TTS"][2] < 0.5 && refWm < 0.5, "워터마크는 Chatterbox만 > 0.5 이어야 해요");

