function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

function chirp(f1: number, f2: number, sec: number, sr: number = SR): Float32Array {
  // 시험 신호: f1 -> f2 Hz로 직선으로 올라가는 소리
  const k = (f2 - f1) / sec;
  return Float32Array.from({ length: Math.floor(sec * sr) }, (_, i) => 0.5 * Math.sin(2 * Math.PI * (f1 * (i / sr) + 0.5 * k * (i / sr) ** 2)));
}

const pc = prosody(chirp(150, 300, 2.0));
console.log("시험 신호(150 -> 300 Hz):", { pitchHz: +pc.pitchHz.toFixed(2), rangeSt: +pc.rangeSt.toFixed(2), energyDb: +pc.energyDb.toFixed(2), silence: +pc.silence.toFixed(2) });

const text = "드디어 합격했어요! 정말 믿기지가 않아요!";
const rows: Record<string, ReturnType<typeof prosody>> = {};
for (const ex of [0.25, 1.0]) {
  const p = prosody(generate(text, ex, 0.5, 3), SR, text);
  rows[String(ex)] = p;
  console.log(`exaggeration ${ex}: 음높이 폭 ${p.rangeSt.toFixed(1)} 반음 · 세기 변화 ${p.energyDb.toFixed(1)} dB · ${p.sylPerSec.toFixed(1)} 음절/초`);
}
check(Math.abs(pc.rangeSt - 9.6) < 1.2 && pc.pitchHz > 190 && pc.pitchHz < 235
  && rows["1"].rangeSt > rows["0.25"].rangeSt && rows["1"].energyDb > rows["0.25"].energyDb,
  "측정기: 음높이 폭 9.6반음 근처, 중앙값 190~235 Hz");

arnar.typescript:
// D18 · Part 2 · AR vs NAR: 순차 호출 수와 오류 누적 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d18_arnar.ts
//   AR(Chatterbox)은 토큰마다 한 번씩 순서대로 부르고, NAR(F5-TTS)은 길이와 상관없이 nfe번만 부른다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const TOKEN_HZ = 25;
const NFE = 16;
// 자기회귀: 소리 토큰 하나당 한 번, 앞 결과가 있어야 다음을 부를 수 있어 병렬화가 어렵다
const arCalls = (sec: number): number => Math.floor(sec * TOKEN_HZ) + 1;
// 비자기회귀: 모든 프레임을 한꺼번에 nfe번 다듬는다 (호출 횟수가 길이와 무관)
const narCalls = (_sec: number): number => NFE;
// 토큰 하나가 어긋날 확률이 pErr일 때 끝까지 깨끗할 확률. 앞의 오류가 뒤로 번질 수 있어 길수록 위험
const arCleanProb = (sec: number, pErr = 0.0005): number => (1 - pErr) ** arCalls(sec);

console.log(`${"길이(초)".padStart(8)} ${"AR 호출".padStart(8)} ${"NAR 호출".padStart(9)} ${"AR 깨끗할 확률".padStart(14)}`);
for (const sec of [2, 5, 10, 20]) {
  console.log(`${String(sec).padStart(8)} ${String(arCalls(sec)).padStart(8)} ${String(narCalls(sec)).padStart(9)} ${arCleanProb(sec).toFixed(3).padStart(14)}`);
}
check(arCalls(20) === 4 * arCalls(5) - 3 && narCalls(2) === narCalls(20) && narCalls(20) === NFE
  && arCalls(2) > 0 && arCalls(20) > narCalls(20) && narCalls(20) > arCalls(0.5) && arCleanProb(20) < arCleanProb(2),
  "AR은 길이에 비례해 늘고, NAR은 일정해야 해요");
